// Generates schema.sql (PGlite fixture) from columns-2026-09-22.mjs. Deterministic; the catalog test fails if
// the committed schema.sql differs from a fresh generation (principle 3).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { TABLES, SYNTHETIC, DRAFT_057, V5_073, SNAPSHOT } from './columns-2026-09-22.mjs';
const TY = { int8: 'bigint', int4: 'integer', int2: 'smallint', text: 'text', timestamptz: 'timestamptz', date: 'date',
  numeric: 'numeric', bool: 'boolean', jsonb: 'jsonb', bpchar: 'char(2)', _text: 'text[]', uuid: 'uuid' };
const col = ([c, t]) => {
  const nn = t.endsWith('!'); const base = t.replace('!', ''); let d = `${c} ${TY[base] || (() => { throw new Error('type ' + t); })()}`;
  if (c === 'id' && nn) d += ' GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY';
  else if (nn) d += ' NOT NULL' + (base === 'timestamptz' ? ' DEFAULT now()' : base === 'bool' ? ' DEFAULT false' : base === 'int4' ? ' DEFAULT 0' : '');
  return d;
};
export function schemaSql() {
  const out = [`-- GENERATED by tms-auditor/test/fixtures/build-schema.mjs from ${SNAPSHOT}. Do not edit.`,
    '-- Local fixture only: production types/columns, NO constraints/triggers/data. ids are identities for convenience.'];
  const emit = (name, cols, note) => {
    out.push(`${note ? '-- ' + note + '\n' : ''}CREATE TABLE public.${name} (\n${cols.map((x) => '  ' + col(x)).join(',\n')}\n);`);
  };
  for (const [t, cols] of Object.entries(TABLES)) emit(t, cols);
  for (const [t, cols] of Object.entries(SYNTHETIC)) emit(t, cols, 'SYNTHETIC (not from the production catalog)');
  const D57 = 'SYNTHETIC from DRAFT 057, until it runs';
  for (const [t, cols] of Object.entries(DRAFT_057.tables)) emit(t, cols, D57);
  for (const [t, cols] of Object.entries(DRAFT_057.columns)) out.push(`-- ${D57}\n` + cols.map((x) => `ALTER TABLE public.${t} ADD COLUMN ${col(x)};`).join('\n'));
  return out.join('\n') + '\n';
}
// The v5 stand-ins (071, 072b and 073, all executed) in their own file: harnesses that apply 071 on the fixture
// load without it ({ v5: false }), and schema.sql stays byte for byte what it was.
export function schemaV5Sql() {
  const out = [`-- GENERATED by tms-auditor/test/fixtures/build-schema.mjs (V5_073). Do not edit.`,
    '-- SYNTHETIC from 071 (executed), DRAFT 072b and DRAFT 073, until the next snapshot. Loaded by createDb unless { v5: false }.'];
  for (const [t, cols] of Object.entries(V5_073.tables)) out.push(`CREATE TABLE public.${t} (\n${cols.map((x) => '  ' + col(x)).join(',\n')}\n);`);
  for (const [t, cols] of Object.entries(V5_073.columns)) out.push(cols.map((x) => `ALTER TABLE public.${t} ADD COLUMN ${col(x)};`).join('\n'));
  return out.join('\n') + '\n';
}
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  fs.writeFileSync(path.join(path.dirname(fileURLToPath(import.meta.url)), 'schema-v5.sql'), schemaV5Sql());
  fs.writeFileSync(path.join(path.dirname(fileURLToPath(import.meta.url)), 'schema.sql'), schemaSql());
  console.log('schema.sql:', Object.keys(TABLES).length, 'tables +', Object.keys(SYNTHETIC).length, 'synthetic +',
    Object.keys(DRAFT_057.tables).length, 'tables/views and', Object.values(DRAFT_057.columns).flat().length, 'columns from DRAFT 057');
  console.log('schema-v5.sql:', Object.keys(V5_073.tables).length, 'tables/views and', Object.values(V5_073.columns).flat().length, 'columns from 071 / DRAFT 072b / DRAFT 073');
}
